parameters.jsCode:
// Freitext aus einem Formular ist selten sauber: Grossschreibung, doppelte
// Leerzeichen, versehentlich ganze Fragen statt eines Keywords. Ohne
// Normalisierung liefert die SERP-API entweder Muell oder gar nichts.
const raus = [];

for (const eintrag of $input.all()) {
  const f = eintrag.json || {};
  const keyword = String(f['Haupt-Keyword'] || '').trim().replace(/\s+/g, ' ').toLowerCase();
  const zielmarkt = String(f['Zielmarkt'] || 'Deutschland (de)');

  // Die SERP-APIs erwarten englische Laendernamen, das Formular zeigt deutsche.
  let land = 'Germany';
  if (zielmarkt.includes('Oesterreich')) land = 'Austria';
  if (zielmarkt.includes('Schweiz')) land = 'Switzerland';

  const woerter = keyword ? keyword.split(' ').length : 0;
  const maengel = [];
  if (keyword.length < 3) maengel.push('Keyword ist zu kurz oder leer');
  if (woerter > 8) maengel.push('Das sieht nach einem ganzen Satz aus, nicht nach einem Keyword');
  if (/https?:\/\//.test(keyword)) maengel.push('Bitte ein Keyword eintragen, keine URL');

  raus.push({
    json: {
      keyword,
      wortanzahl_keyword: woerter,
      zielgruppe: String(f['Zielgruppe'] || '').trim(),
      zielmarkt,
      land,
      sprachcode: 'de',
      seitentyp: String(f['Seitentyp'] || 'Ratgeber / Blogartikel'),
      empfaenger: String(f['E-Mail fuer das Briefing'] || '').trim(),
      angefragt_am: new Date().toLocaleDateString('de-DE'),
      eingabe_brauchbar: maengel.length === 0,
      eingabe_maengel: maengel.join('; ')
    }
  });
}
return raus;

// Die beiden gaengigen Anbieter liefern voellig unterschiedliche Strukturen.
// Statt den Nutzer auf einen festzunageln, lesen wir beide Formen — und liefern
// notfalls ein leeres, aber gueltiges Ergebnis, damit die KI trotzdem ein
// Briefing auf Basis von Keyword und Seitentyp bauen kann.
const anfrage = $('Anfrage aufbereiten').item.json;
const antwort = $input.first().json || {};

let treffer = [];
let fragen = [];

// Variante DataForSEO
const dfs = antwort.tasks?.[0]?.result?.[0]?.items;
if (Array.isArray(dfs)) {
  treffer = dfs.filter(i => i.type === 'organic').map(i => ({ position: i.rank_group, titel: i.title, beschreibung: i.description, url: i.url, domain: i.domain }));
  const paa = dfs.find(i => i.type === 'people_also_ask');
  fragen = (paa?.items || []).map(i => i.title).filter(Boolean);
}

// Variante SerpAPI
if (treffer.length === 0 && Array.isArray(antwort.organic_results)) {
  treffer = antwort.organic_results.map(i => ({ position: i.position, titel: i.title, beschreibung: i.snippet, url: i.link, domain: (i.displayed_link || '').split('/')[0] }));
  fragen = (antwort.related_questions || []).map(i => i.question).filter(Boolean);
}

const top = treffer.slice(0, 10);

// Grobe Laengenindikation: Wie ausfuehrlich sind die Snippets der Top-Treffer?
// Ersetzt keine echte Wortzahlmessung, gibt der KI aber einen Anhaltspunkt.
const snippetLaenge = top.length
  ? Math.round(top.reduce((s, t) => s + String(t.beschreibung || '').length, 0) / top.length)
  : 0;

// Verzeichnisse und Portale zeigen an, ob das Keyword ueberhaupt fuer eine
// eigene Unternehmensseite erreichbar ist oder von Aggregatoren besetzt wird.
const portale = ['wikipedia.org', 'amazon.de', 'idealo.de', 'gelbeseiten.de', 'youtube.com', 'reddit.com', 'gutefrage.net'];
const portalanteil = top.length ? top.filter(t => portale.some(p => String(t.domain || '').includes(p))).length / top.length : 0;

return [{
  json: {
    ...anfrage,
    serp_verfuegbar: top.length > 0,
    anzahl_treffer: top.length,
    top_ergebnisse: top,
    verwandte_fragen: fragen.slice(0, 12),
    durchschnittliche_snippet_laenge: snippetLaenge,
    portalanteil_prozent: Math.round(portalanteil * 100),
    serp_hinweis: top.length === 0 ? 'Keine SERP-Daten erhalten - Briefing basiert nur auf Keyword und Seitentyp. API-Zugang und URL pruefen.' : ''
  }
}];

