parameters.jsCode:
// Die KI liefert Struktur, kein lesbares Dokument. Redakteure arbeiten aber
// nicht mit JSON — deshalb hier ein Markdown-Briefing, das sich direkt in
// Google Docs, Notion oder das CMS kopieren laesst.
const analyse = $('Top-Ergebnisse analysieren').item.json;
const b = $input.first().json.message?.content ?? $input.first().json;

const zeilen = [];
zeilen.push('# Content-Briefing: ' + analyse.keyword);
zeilen.push('');
zeilen.push('- Angefragt am: ' + analyse.angefragt_am);
zeilen.push('- Zielgruppe: ' + analyse.zielgruppe);
zeilen.push('- Zielmarkt: ' + analyse.zielmarkt);
zeilen.push('- Seitentyp: ' + analyse.seitentyp);
zeilen.push('- Suchintention: ' + (b.suchintention || 'unklar'));
zeilen.push('- Kernfrage der Nutzer: ' + (b.nutzerfrage || '-'));
zeilen.push('- Empfohlene Wortzahl: ' + (b.empfohlene_wortzahl || '-') + ' (' + (b.wortzahl_begruendung || '') + ')');
zeilen.push('');
zeilen.push('## Meta-Angaben');
zeilen.push('- Title: ' + (b.meta_title || '-'));
zeilen.push('- Description: ' + (b.meta_description || '-'));
zeilen.push('');
zeilen.push('## Einstieg');
zeilen.push(b.einstiegsabsatz || '-');
zeilen.push('');
zeilen.push('## Gliederung');
const gliederung = Array.isArray(b.gliederung) ? b.gliederung : [];
for (const abschnitt of gliederung) {
  zeilen.push('### ' + (abschnitt.h2 || '-'));
  for (const h3 of (abschnitt.h3 || [])) zeilen.push('- ' + h3);
  zeilen.push('');
}
const liste = (titel, werte) => {
  zeilen.push('## ' + titel);
  const w = Array.isArray(werte) ? werte : [];
  if (w.length === 0) zeilen.push('- (keine Angabe)');
  for (const x of w) zeilen.push('- ' + x);
  zeilen.push('');
};
liste('Fragen, die beantwortet werden muessen', b.pflichtfragen);
liste('Pflichtbegriffe und Entitaeten', b.pflichtbegriffe);
liste('Luecken der aktuellen Top-Treffer', b.luecken);
liste('Interne Verlinkung pruefen', b.interne_verlinkung);

zeilen.push('## Aktuelle Top-Treffer');
for (const t of (analyse.top_ergebnisse || []).slice(0, 10)) {
  zeilen.push('- ' + t.position + '. ' + t.titel + ' (' + t.domain + ')');
}
zeilen.push('');
zeilen.push('> Hinweis: KI-generierter Vorschlag auf Basis oeffentlicher Suchergebnisse. Inhalte eigenstaendig recherchieren und formulieren, keine Passagen aus den Wettbewerberseiten uebernehmen.');

const warnungen = [];
if (analyse.serp_hinweis) warnungen.push(analyse.serp_hinweis);
if (b.warnung) warnungen.push(b.warnung);
if (analyse.portalanteil_prozent >= 50) warnungen.push('Mehr als die Haelfte der Top-Treffer sind Portale oder Verzeichnisse - eigene Rankingchancen pruefen.');

return [{
  json: {
    keyword: analyse.keyword,
    zielmarkt: analyse.zielmarkt,
    seitentyp: analyse.seitentyp,
    empfaenger: analyse.empfaenger,
    angefragt_am: analyse.angefragt_am,
    suchintention: b.suchintention || '',
    empfohlene_wortzahl: b.empfohlene_wortzahl || 0,
    gliederung_kurz: gliederung.map(a => a.h2).join(' | '),
    pflichtfragen_kurz: (b.pflichtfragen || []).join(' | '),
    wettbewerber: (analyse.top_ergebnisse || []).slice(0, 5).map(t => t.domain).join(', '),
    warnungen: warnungen.join(' '),
    briefing_markdown: zeilen.join('\n')
  }
}];

